window.DD_NEW = [

/* ---------- John Hope Bryant ---------- */
{id:"bryant-01",au:"bryant",s:"Financial Dignity",a:"I treat financial literacy as a civil rights matter, because not knowing the rules of money is how people stay locked out.",p:"Learn one financial term properly today \u2014 APR, compounding, amortisation \u2014 and explain it to somebody else.",k:["financial literacy","civil rights","knowledge","exclusion"],src:"After Bryant on financial literacy as the civil rights issue of this generation"},
{id:"bryant-02",au:"bryant",s:"Financial Dignity",a:"Civil rights got me the seat; silver rights are about being able to afford the meal.",p:"Name one economic goal that would change your family's options, and write the first step under it.",k:["silver rights","economics","opportunity","ownership"],src:"After Bryant's \u201cfrom civil rights to silver rights\u201d framing"},
{id:"bryant-03",au:"bryant",s:"Financial Dignity",a:"My credit score is not a judgment on my worth; it is a number I can move with information and time.",p:"Check your credit report this week and fix or dispute one thing on it.",k:["credit","score","repair","agency"],src:"After Bryant and the 700 Credit Score Club"},
{id:"bryant-04",au:"bryant",s:"Financial Dignity",a:"Poverty is not only a shortage of money; it is a shortage of confidence, role models and working information.",p:"Identify which of those four you are shortest on right now, and address that one first.",k:["poverty","confidence","information","mindset"],src:"After Bryant on redefining poverty and wealth"},
{id:"bryant-05",au:"bryant",s:"Financial Dignity",a:"I invest for the long term rather than speculate for the thrill; the two only look alike from a distance.",p:"Before your next financial decision, ask whether you're buying an asset or buying excitement.",k:["investing","speculation","patience","discipline"],src:"After Financial Literacy for All"},
{id:"bryant-06",au:"bryant",s:"Love Leadership",a:"Loss made me a leader; there is no depth without some legitimate suffering behind it.",p:"Write down what one hard season actually taught you that comfort could not have.",k:["loss","leadership","suffering","depth"],src:"After the first law in Love Leadership: loss creates leaders"},
{id:"bryant-07",au:"bryant",s:"Love Leadership",a:"Fear can start a movement but it cannot sustain one; only respect keeps people in the room.",p:"Find one place where you're using pressure, and replace it with a reason.",k:["fear","respect","motivation","leadership"],src:"After the second law in Love Leadership: fear fails"},
{id:"bryant-08",au:"bryant",s:"Love Leadership",a:"Doing right by people is not the opposite of doing well; over a long enough horizon it is the mechanism.",p:"Choose the option that serves the other party best in one negotiation this month, and watch what returns.",k:["ethics","profit","trust","long game"],src:"After the third law in Love Leadership: love makes money"},
{id:"bryant-09",au:"bryant",s:"Love Leadership",a:"When I open up first, other people stop performing \u2014 vulnerability is leverage, not exposure.",p:"Admit one thing you don't know in a meeting where you'd normally bluff.",k:["vulnerability","honesty","openness","power"],src:"After the fourth law in Love Leadership: vulnerability is power"},
{id:"bryant-10",au:"bryant",s:"Love Leadership",a:"I give before I'm asked and before I'm certain of the return, because that is the whole trick.",p:"Do one useful thing for someone this week with no expectation attached.",k:["giving","generosity","reciprocity","service"],src:"After the fifth law in Love Leadership: giving is getting"},
{id:"bryant-11",au:"bryant",s:"Mindset",a:"I am moving from survivor to thriver to winner, and I refuse to mistake the first stage for my ceiling.",p:"Name which stage you're actually in, and the one behaviour that belongs to the next one.",k:["mindset","survivor","thriver","winner"],src:"After Up From Nothing"},
{id:"bryant-12",au:"bryant",s:"Mindset",a:"I believed I was a winner before I had won anything; that order is not arrogance, it's sequence.",p:"Do one thing today in the manner of the person you intend to become.",k:["self-belief","identity","confidence","sequence"],src:"After Up From Nothing on believing before winning"},
{id:"bryant-13",au:"bryant",s:"Mindset",a:"My self-esteem is infrastructure; without it every other resource leaks away.",p:"Keep one small promise to yourself today, purely to prove your own word is good.",k:["self-esteem","promises","integrity","foundation"],src:"After the Five Pillars of Success"},
{id:"bryant-14",au:"bryant",s:"Mindset",a:"I don't wait for the system to be fair before I learn how it works.",p:"Learn one rule of a system that has cost you \u2014 tax, credit, hiring \u2014 and use it this month.",k:["systems","pragmatism","knowledge","agency"],src:"After Bryant on operating inside an imperfect economy"},
{id:"bryant-15",au:"bryant",s:"Community & Role Models",a:"Somebody once walked into my classroom and showed me a life I didn't know existed; I try to be that for someone else.",p:"Offer twenty minutes to one young person who has never met anyone doing your job.",k:["role models","mentoring","visibility","service"],src:"After Bryant's account of the banker who visited his school"},
{id:"bryant-16",au:"bryant",s:"Community & Role Models",a:"You cannot become what you have never seen, so I make sure other people can see it.",p:"Talk publicly about how you actually got where you are, including the unglamorous parts.",k:["representation","example","aspiration","honesty"],src:"After the Five Pillars of Success: supportive role models"},
{id:"bryant-17",au:"bryant",s:"Community & Role Models",a:"Rebuilding one street is more useful than diagnosing a whole country.",p:"Pick one street, block or institution near you and do something concrete for it.",k:["community","local","action","practicality"],src:"After Operation HOPE's on-the-ground model"},
{id:"bryant-18",au:"bryant",s:"Community & Role Models",a:"I want a capitalism that works for more people, so I aim to widen the ladder rather than only climb it.",p:"Find one way your work could open a door for somebody outside your usual circle.",k:["capitalism","inclusion","access","ladder"],src:"After How the Poor Can Save Capitalism and Capitalism For All"},

/* ---------- Viktor Frankl ---------- */
{id:"frankl-01",au:"frankl",s:"Meaning",a:"Between what happens to me and how I answer it, there is a space \u2014 and that space is mine.",p:"Notice one moment today where you paused before reacting, and lengthen the next one.",k:["freedom","response","attitude","choice"],src:"After Frankl on the last of the human freedoms"},
{id:"frankl-02",au:"frankl",s:"Meaning",a:"When I stop asking what I want from life and start answering what life is asking of me, the question gets solvable.",p:"Ask what your current situation is actually requiring of you, then do that one thing.",k:["meaning","responsibility","questions","purpose"],src:"After Man's Search for Meaning"},
{id:"frankl-03",au:"frankl",s:"Meaning",a:"A strong enough reason will carry me through almost any conditions.",p:"Write your reason down in one sentence and put it where you'll see it on a bad morning.",k:["why","endurance","purpose","resilience"],src:"After Frankl on having a why to bear almost any how"},
{id:"frankl-04",au:"frankl",s:"Meaning",a:"Happiness will not come when chased; it arrives sideways, as a by-product of something worth doing.",p:"Stop optimising for how you feel today and pick something worth finishing instead.",k:["happiness","pursuit","by-product","work"],src:"After Frankl on happiness ensuing rather than being pursued"},
{id:"frankl-05",au:"frankl",s:"Meaning",a:"I find meaning in three places: in work, in love, and in the courage I bring to unavoidable suffering.",p:"Identify which of the three is currently carrying you, and tend to the weakest.",k:["work","love","suffering","logotherapy"],src:"After the three sources of meaning in logotherapy"},
{id:"frankl-06",au:"frankl",s:"Meaning",a:"When a situation cannot be changed, the task becomes changing myself in relation to it.",p:"Name one fixed circumstance and one thing about your posture towards it you could alter.",k:["acceptance","adaptation","change","posture"],src:"After Frankl on unchangeable circumstances"},
{id:"frankl-07",au:"frankl",s:"Meaning",a:"I live as though I am living for the second time, and about to repeat a mistake I can still avoid.",p:"Apply that test to one decision on today's list.",k:["hindsight","decisions","regret","clarity"],src:"After Frankl's categorical imperative of logotherapy"},
{id:"frankl-08",au:"frankl",s:"Meaning",a:"Optimism is not a denial of the facts; it is what I do after I have admitted them.",p:"State the worst honest reading of your situation, then name one action still available.",k:["tragic optimism","realism","hope","action"],src:"After Frankl on tragic optimism"},
{id:"frankl-09",au:"frankl",s:"Meaning",a:"I aim past myself \u2014 at a cause or a person \u2014 because that is the only way I reliably become more myself.",p:"Do one thing today whose benefit lands entirely on somebody else.",k:["self-transcendence","service","purpose","others"],src:"After Frankl on self-transcendence"},
{id:"frankl-10",au:"frankl",s:"Meaning",a:"Nothing that I have already done or lived can be taken from me; the past is the one safe place to store a life.",p:"Write down one thing you have already done that no future loss can undo.",k:["past","permanence","memory","security"],src:"After Frankl on the granary of the past"},

/* ---------- Howard Thurman ---------- */
{id:"thurman-01",au:"thurman",s:"Inner Life",a:"I ask what makes me come alive, then go and do that, because the world needs people who have woken up.",p:"Name the last time you felt fully awake, and schedule more of whatever caused it.",k:["aliveness","vocation","calling","energy"],src:"After Thurman's counsel on what the world needs"},
{id:"thurman-02",au:"thurman",s:"Inner Life",a:"I listen for the sound of the genuine in myself, under all the noise other people have installed.",p:"Sit for five minutes without input and notice what you actually think.",k:["authenticity","silence","self-knowledge","noise"],src:"After Thurman on the sound of the genuine"},
{id:"thurman-03",au:"thurman",s:"Inner Life",a:"I centre down before I act, because a hurried decision is usually somebody else's decision.",p:"Take three slow breaths before answering the next thing that demands an answer.",k:["stillness","centering","pause","discernment"],src:"After Thurman on centering down"},
{id:"thurman-04",au:"thurman",s:"Inner Life",a:"Fear, deception and hatred are the three things that hollow out the powerless; I refuse all three.",p:"Identify which of the three has the strongest grip on you at the moment, and name it out loud.",k:["fear","deception","hate","dignity"],src:"After Jesus and the Disinherited"},
{id:"thurman-05",au:"thurman",s:"Inner Life",a:"My dignity is not issued by anybody else, so it cannot be withdrawn by them either.",p:"Notice one place you've been waiting for permission, and stop waiting.",k:["dignity","permission","worth","independence"],src:"After Jesus and the Disinherited on inner authority"},
{id:"thurman-06",au:"thurman",s:"Inner Life",a:"Hatred takes more from the one who carries it than from the one it is aimed at.",p:"Set down one grievance today \u2014 not for their sake, for the weight.",k:["hatred","resentment","release","cost"],src:"After Thurman on the corrosive work of hate"},
{id:"thurman-07",au:"thurman",s:"Inner Life",a:"I look for common ground first, because it is the only ground anything gets built on.",p:"In your next disagreement, state what you agree on before what you don't.",k:["common ground","conflict","dialogue","building"],src:"After The Search for Common Ground"},
{id:"thurman-08",au:"thurman",s:"Inner Life",a:"I keep a place inside that the day cannot reach, and I visit it before the day starts.",p:"Protect the first ten minutes after you wake from anyone else's agenda.",k:["solitude","morning","interior","protection"],src:"After Thurman on the inner sanctuary"},
{id:"thurman-09",au:"thurman",s:"Inner Life",a:"A person's back is only stiffened by being met, not by being flattered.",p:"Tell one person something true and encouraging that they can actually act on.",k:["encouragement","truth","support","strength"],src:"After Thurman on ministering to the disinherited"},
{id:"thurman-10",au:"thurman",s:"Inner Life",a:"I do not have to be sure of the whole road to take the next honest step on it.",p:"Take the next step you can see, and stop demanding a map first.",k:["uncertainty","next step","faith","action"],src:"After Thurman on walking without the whole map"},

/* ---------- Noam Chomsky ---------- */
{id:"chomsky-01",au:"chomsky",s:"Attention & Consent",a:"The trick is not to shut down debate but to set its edges, so that vigorous argument inside a narrow frame feels like free thought.",p:"Name one question your field treats as settled, and ask who benefits from it staying settled.",k:["media","framing","debate","consent"],src:"After Manufacturing Consent on the bounds of permissible opinion"},
{id:"chomsky-02",au:"chomsky",s:"Attention & Consent",a:"Before I weigh what an outlet tells me, I ask who owns it, who pays for it, and who it has to stay friendly with to keep working.",p:"Look up the ownership and funding of one source you rely on weekly.",k:["ownership","funding","sources","scepticism"],src:"After the propaganda model's filters in Manufacturing Consent"},
{id:"chomsky-03",au:"chomsky",s:"Attention & Consent",a:"Where people cannot simply be compelled, they have to be persuaded, and that makes persuasion the more interesting thing to study.",p:"Pick one thing you believe strongly and trace where you first heard it.",k:["consent","persuasion","power","origins"],src:"After Manufacturing Consent on control by persuasion rather than force"},
{id:"chomsky-04",au:"chomsky",s:"Attention & Consent",a:"A format that allows only thirty seconds guarantees conventional answers, because anything unfamiliar would need evidence and evidence takes time.",p:"Give one complicated view the full hearing it needs before judging it.",k:["concision","format","conformity","evidence"],src:"After Chomsky's critique of concision in broadcast media"},
{id:"chomsky-05",au:"chomsky",s:"Attention & Consent",a:"I notice which victims get names and which get numbers; the difference is rarely about the scale of the harm.",p:"Compare the coverage two comparable tragedies received, and ask what separated them.",k:["victims","coverage","attention","asymmetry"],src:"After the worthy and unworthy victims analysis in Manufacturing Consent"},
{id:"chomsky-06",au:"chomsky",s:"Attention & Consent",a:"If I can see clearly and say so without much risk, then saying so is not brave — it is simply the job.",p:"Say the accurate thing in the room where it costs you something, not only where it is safe.",k:["responsibility","truth","privilege","courage"],src:"After “The Responsibility of Intellectuals” (1967)"},
{id:"chomsky-07",au:"chomsky",s:"Attention & Consent",a:"Denouncing the crimes of my opponents costs me nothing; the test is what I say about the ones committed in my name.",p:"Apply your strongest standard to your own side once this week.",k:["consistency","self-criticism","standards","honesty"],src:"After Chomsky on applying moral standards to one's own state first"},
{id:"chomsky-08",au:"chomsky",s:"Attention & Consent",a:"Any authority over me should have to explain itself; the ones that cannot are simply habits wearing a uniform.",p:"Ask one rule you follow automatically to justify itself, and see whether it can.",k:["authority","justification","hierarchy","questioning"],src:"After Chomsky's anarchist principle that authority must justify itself"},
{id:"chomsky-09",au:"chomsky",s:"Attention & Consent",a:"Forgetting is not neutral; what a society drops out of its memory tells you exactly what it found inconvenient.",p:"Read one account of an event you only know through summary.",k:["memory","history","omission","record"],src:"After Chomsky on historical amnesia in public discussion"},
{id:"chomsky-10",au:"chomsky",s:"Attention & Consent",a:"If I decide nothing can change, I have chosen the outcome in advance and called it realism.",p:"Take one action on a problem you have privately written off.",k:["hope","fatalism","agency","action"],src:"After Chomsky on optimism as a precondition for acting"},
{id:"chomsky-11",au:"chomsky",s:"Language & Mind",a:"A child is not handed language so much as issued the equipment to build it, which is why the building goes so fast.",p:"Watch a small child construct a sentence nobody taught them, and notice what that implies.",k:["language","innateness","universal grammar","development"],src:"After Chomsky's account of an innate language faculty"},
{id:"chomsky-12",au:"chomsky",s:"Language & Mind",a:"Children end up knowing far more about their language than anything they actually heard could have told them.",p:"Notice one rule you follow perfectly in speech but were never taught.",k:["poverty of the stimulus","learning","knowledge","input"],src:"After the poverty of the stimulus argument"},
{id:"chomsky-13",au:"chomsky",s:"Language & Mind",a:"With a limited stock of words and rules I can say a sentence that has never been said, and be understood the first time.",p:"Write one sentence today that you are confident nobody has written before.",k:["creativity","generativity","language","finite means"],src:"After Chomsky's development of Humboldt on the infinite use of finite means"},
{id:"chomsky-14",au:"chomsky",s:"Language & Mind",a:"An education can train me to inquire or train me to comply, and the two look similar from the outside for a long time.",p:"Ask one question in a class or meeting that the format does not expect.",k:["education","inquiry","obedience","questioning"],src:"After Chomsky on education as inquiry against education as indoctrination"},
{id:"chomsky-15",au:"chomsky",s:"Language & Mind",a:"The question I am permitted to ask has already narrowed the answers I can reach.",p:"Rewrite one problem you are stuck on as a different question entirely.",k:["framing","questions","assumptions","reframing"],src:"After Chomsky on how the framing of a question constrains its answers"},

/* ---------- Peter Singer ---------- */
{id:"singer-01",au:"singer",s:"Obligation & Distance",a:"If I would ruin my shoes to pull a child from a pond, then distance alone cannot be what excuses me the rest of the time.",p:"Set up one small recurring donation where the money demonstrably prevents suffering.",k:["obligation","distance","giving","ethics"],src:"After “Famine, Affluence, and Morality” (1972) and the drowning child argument"},
{id:"singer-02",au:"singer",s:"Obligation & Distance",a:"The question was never how clever a creature is, but whether it can suffer — and that changes who my choices have to account for.",p:"Weigh one routine habit against the suffering it requires, then keep it or change it deliberately.",k:["suffering","animals","consideration","consistency"],src:"After Animal Liberation on the capacity to suffer as the basis of moral consideration"},
{id:"singer-03",au:"singer",s:"Obligation & Distance",a:"Good intentions are not the unit of measurement; the unit is how much suffering actually ended per pound I gave.",p:"Check whether your regular donation has any evidence behind it, and switch if it does not.",k:["effectiveness","evidence","giving","measurement"],src:"After The Life You Can Save and the effective altruism argument"},
{id:"singer-04",au:"singer",s:"Obligation & Distance",a:"Money spent on something I did not need was not idle; it was money that had another use, and I chose this one.",p:"Price one recent non-essential purchase against what the same amount does elsewhere.",k:["luxury","trade-offs","spending","choice"],src:"After Singer on the cost of affluence in “Famine, Affluence, and Morality”"},
{id:"singer-05",au:"singer",s:"Obligation & Distance",a:"Whether a person is near me or far from me changes how I feel about their trouble, but it does not change their trouble.",p:"Act once on a need you know is real but cannot see.",k:["proximity","impartiality","feeling","duty"],src:"After Singer on the moral irrelevance of physical distance"},
{id:"singer-06",au:"singer",s:"Obligation & Distance",a:"I would rather give steadily by arrangement than generously by mood, because moods are not reliable and arrangements are.",p:"Convert one occasional donation into a standing one, at an amount you will not resent.",k:["consistency","commitment","habit","giving"],src:"After The Life You Can Save on pledging a set share of income"},
{id:"singer-07",au:"singer",s:"Obligation & Distance",a:"Being one of many who could help does not divide my share of the duty into something too small to bother with.",p:"Do the thing you have been assuming somebody better placed will do.",k:["diffusion","responsibility","duty","bystander"],src:"After Singer on shared responsibility not dissolving individual obligation"},
{id:"singer-08",au:"singer",s:"Obligation & Distance",a:"A story moves me more than a statistic, which tells me something about my wiring rather than about where the need is greatest.",p:"Choose one cause by the numbers this year rather than by the story that reached you.",k:["statistics","narrative","bias","allocation"],src:"After Singer on emotional salience distorting where help goes"},
{id:"singer-09",au:"singer",s:"Widening the Circle",a:"The list of who counts has been revised upward in every century, which makes me suspect the current list is also too short.",p:"Name one group your decisions affect but your reasoning never mentions.",k:["moral circle","history","inclusion","revision"],src:"After The Expanding Circle on the widening boundary of moral concern"},
{id:"singer-10",au:"singer",s:"Widening the Circle",a:"Preferring my own kind purely because it is my own kind is the shape of every prejudice I claim to have outgrown.",p:"Test one preference you hold for a reason other than the group it favours.",k:["speciesism","prejudice","consistency","reasoning"],src:"After Animal Liberation on speciesism as a prejudice of familiar form"},
{id:"singer-11",au:"singer",s:"Widening the Circle",a:"Equal consideration does not mean identical treatment; it means nobody's interest gets discounted for being theirs rather than mine.",p:"In one decision today, weigh the other party's interest at full value.",k:["equality","interests","fairness","consideration"],src:"After Practical Ethics on the principle of equal consideration of interests"},
{id:"singer-12",au:"singer",s:"Widening the Circle",a:"An intuition that survives being examined is worth keeping; one that only survives being unexamined is not.",p:"Take one strong moral reaction and try to state the reason underneath it.",k:["intuition","reasoning","examination","ethics"],src:"After Practical Ethics on subjecting moral intuitions to argument"},
{id:"singer-13",au:"singer",s:"Widening the Circle",a:"If somebody's argument defeats mine, the honourable move is to change my position rather than my opponent.",p:"Write down what evidence would change your mind on something you argue often.",k:["argument","openness","revision","honesty"],src:"After Singer on following the argument where it leads"},
{id:"singer-14",au:"singer",s:"Widening the Circle",a:"Extreme poverty is not a fixed feature of the world; it is a problem with a price, and the price is affordable.",p:"Find out what one specific intervention costs per life improved.",k:["poverty","solvable","cost","action"],src:"After The Life You Can Save on global poverty as a tractable problem"},
{id:"singer-15",au:"singer",s:"Widening the Circle",a:"The pond does not stop being a pond because there are many children in it and I am tired.",p:"Return to one obligation you quietly retired because it felt endless.",k:["fatigue","obligation","persistence","scale"],src:"After Singer on the drowning child argument extended to repeated need"},

/* ---------- Frederick Douglass ---------- */
{id:"douglass-01",au:"douglass",s:"Freedom & Struggle",a:"Nothing has ever been handed to me by power that I did not first ask for plainly, and keep asking for.",p:"Turn one thing you've been hinting at into a plain request, made to the person who can actually grant it.",k:["power","demand","asking","persistence"],src:"After Douglass's 1857 West India Emancipation address on power and demands"},
{id:"douglass-02",au:"douglass",s:"Freedom & Struggle",a:"I stopped expecting the harvest without the ploughing; wanting the outcome while refusing the difficulty is only wishing.",p:"Name the specific unpleasant work your goal requires, and do the first hour of it today.",k:["struggle","effort","progress","honesty"],src:"After Douglass on wanting crops without ploughing the ground"},
{id:"douglass-03",au:"douglass",s:"Freedom & Struggle",a:"I keep raising the thing rather than letting it settle quietly, because quiet is the condition injustice needs.",p:"Say the uncomfortable thing again, once more, in the room where it can change something.",k:["agitation","persistence","silence","courage"],src:"After Douglass's lifelong counsel to agitate"},
{id:"douglass-04",au:"douglass",s:"Freedom & Struggle",a:"A right that nobody is able to exercise is a promise, not a freedom.",p:"Ask of one policy or principle you support: who actually can use this, and who cannot?",k:["rights","freedom","practice","power"],src:"After Douglass on the unfinished work following emancipation"},
{id:"douglass-05",au:"douglass",s:"Freedom & Struggle",a:"I hold a nation to the words it chose for itself; the distance between the creed and the conduct is the whole argument.",p:"Measure one institution you belong to against its own stated values, in writing.",k:["hypocrisy","ideals","accountability","creed"],src:"After “What to the Slave Is the Fourth of July?” (1852)"},
{id:"douglass-06",au:"douglass",s:"Freedom & Struggle",a:"The test of an alliance is the thing it is for, not the company it puts me in.",p:"Judge your next partnership by the work it does, not by who else is in the room.",k:["alliance","principle","coalition","judgement"],src:"After Douglass's stated principle on working with others for a right end"},
{id:"douglass-07",au:"douglass",s:"Self-Making",a:"Learning to read was the thing they worked hardest to keep from me, which told me exactly what it was worth.",p:"Study the subject someone has implied you don't need to understand.",k:["literacy","learning","knowledge","freedom"],src:"After the Narrative on Hugh Auld's warning against teaching him letters"},
{id:"douglass-08",au:"douglass",s:"Self-Making",a:"Whatever I made of myself was made by labour repeated long past the point where it felt heroic.",p:"Return to the ordinary practice you've been waiting to feel inspired about.",k:["work","persistence","self-making","discipline"],src:"After the “Self-Made Men” lecture on the doctrine of work"},
{id:"douglass-09",au:"douglass",s:"Self-Making",a:"Holding power over another person deforms the one who holds it; I watched kindness curdle in someone who had been kind.",p:"Examine one place where you hold power over someone, and check what it is doing to you.",k:["power","corruption","character","self-examination"],src:"After the Narrative on the change in Sophia Auld"},
{id:"douglass-10",au:"douglass",s:"Self-Making",a:"Sorrow can sound like song to a listener who has already decided what he is hearing.",p:"Ask one person what they actually meant, instead of trusting your reading of their mood.",k:["misreading","listening","assumption","attention"],src:"After the Narrative on the meaning of the songs of the enslaved"},

/* ---------- W. E. B. Du Bois ---------- */
{id:"dubois-01",au:"dubois",s:"Education & Identity",a:"I refuse to see myself only through other people's eyes; their measure is not my mirror.",p:"Catch one judgement you've absorbed about yourself and ask who actually wrote it.",k:["double consciousness","self-image","identity","perception"],src:"After The Souls of Black Folk on double consciousness"},
{id:"dubois-02",au:"dubois",s:"Education & Identity",a:"Education is not only training for work; it is the making of a person who can think for themselves.",p:"Read something today that has no career use whatsoever.",k:["education","liberal arts","thinking","utility"],src:"After Du Bois on education beyond vocational training"},
{id:"dubois-03",au:"dubois",s:"Education & Identity",a:"I gather evidence before I argue, because a documented case outlasts a loud one.",p:"Before your next strong claim, find one number or source that supports it.",k:["evidence","scholarship","rigour","argument"],src:"After The Philadelphia Negro and Du Bois's empirical method"},
{id:"dubois-04",au:"dubois",s:"Education & Identity",a:"There is no shame in striving; the shame is in being told the striving is not for me.",p:"Apply for, ask for, or attempt the thing you'd assumed wasn't meant for you.",k:["striving","ambition","aspiration","barriers"],src:"After The Souls of Black Folk on striving"},
{id:"dubois-05",au:"dubois",s:"Education & Identity",a:"The line drawn between people is a problem to be named plainly, not a weather system to be endured.",p:"Name one structural obstacle in your field out loud, accurately, without exaggeration.",k:["colour line","structure","naming","clarity"],src:"After Du Bois on the problem of the colour line"},
{id:"dubois-06",au:"dubois",s:"Education & Identity",a:"I hold two truths at once: the world as it is, and the world I intend to work towards.",p:"Write both versions of one situation and identify the single lever between them.",k:["realism","idealism","tension","strategy"],src:"After Du Bois on holding critique and hope together"},
{id:"dubois-07",au:"dubois",s:"Education & Identity",a:"Culture is inheritance, and I claim mine deliberately rather than receiving it by accident.",p:"Learn one specific thing about where your family came from this month.",k:["heritage","culture","inheritance","roots"],src:"After Du Bois on cultural inheritance"},
{id:"dubois-08",au:"dubois",s:"Education & Identity",a:"Talent unused is not modesty; it is a debt to everyone coming behind me.",p:"Use one capability today that you've been sitting on.",k:["talent","duty","leadership","obligation"],src:"After Du Bois on the obligations of the educated"},
{id:"dubois-09",au:"dubois",s:"Education & Identity",a:"I would rather be uncomfortable and accurate than comfortable and mistaken.",p:"Seek out the strongest version of a view you dislike, and read it properly.",k:["truth","discomfort","accuracy","intellect"],src:"After Du Bois's insistence on unflattering data"},
{id:"dubois-10",au:"dubois",s:"Education & Identity",a:"Progress is not a gift that arrives; it is a thing built by people who kept records.",p:"Document one thing this week that would otherwise go unrecorded.",k:["progress","records","history","evidence"],src:"After Du Bois's lifelong documentary project"},

/* ---------- James Baldwin ---------- */
{id:"baldwin-01",au:"baldwin",s:"Facing Things",a:"Not everything I face can be changed, but nothing changes until I face it.",p:"Name the thing you've been not-looking-at, in writing, today.",k:["facing","denial","change","courage"],src:"After Baldwin on facing what cannot yet be changed"},
{id:"baldwin-02",au:"baldwin",s:"Facing Things",a:"History is not behind me; I carry it, and it shows up in how I react.",p:"Trace one automatic reaction back to where you first learned it.",k:["history","inheritance","reaction","self-knowledge"],src:"After Baldwin on history being present in us"},
{id:"baldwin-03",au:"baldwin",s:"Facing Things",a:"Love is not a soft feeling; it is the state in which growth becomes possible and pretence becomes impossible.",p:"Say one true thing to someone close that you've been softening.",k:["love","honesty","growth","masks"],src:"After The Fire Next Time on love as a growing up"},
{id:"baldwin-04",au:"baldwin",s:"Facing Things",a:"The price of my identity is that I have to actually inhabit it rather than perform it.",p:"Notice one performance you keep up, and drop it for a day.",k:["identity","performance","authenticity","cost"],src:"After The Price of the Ticket"},
{id:"baldwin-05",au:"baldwin",s:"Facing Things",a:"Anger that stays clear is useful; anger that goes blurry only eats the person holding it.",p:"Convert one resentment into a specific, stateable demand or a decision to let go.",k:["anger","clarity","usefulness","resentment"],src:"After Baldwin on rage and clarity"},
{id:"baldwin-06",au:"baldwin",s:"Facing Things",a:"I would rather disturb the peace than keep a peace built on not saying things.",p:"Raise the thing everyone in the room is politely avoiding.",k:["truth-telling","peace","courage","silence"],src:"After Baldwin on the artist as disturber of the peace"},
{id:"baldwin-07",au:"baldwin",s:"Facing Things",a:"People who are hurting other people are usually in trouble themselves; that explains nothing but it clarifies a lot.",p:"Ask what one difficult person is afraid of, before deciding what to do about them.",k:["empathy","conflict","understanding","fear"],src:"After Baldwin on the interior lives of the cruel"},
{id:"baldwin-08",au:"baldwin",s:"Facing Things",a:"I stopped waiting to be accepted on terms set by people who had not examined their own.",p:"Withdraw one request for approval you've been quietly making.",k:["approval","acceptance","terms","independence"],src:"After Baldwin on refusing others' definitions"},
{id:"baldwin-09",au:"baldwin",s:"Facing Things",a:"Innocence that is chosen is not innocence; it is a decision to not know.",p:"Learn the thing about your industry, your city or your family you've preferred not to learn.",k:["innocence","willed ignorance","knowledge","responsibility"],src:"After Baldwin on the crime of innocence"},
{id:"baldwin-10",au:"baldwin",s:"Facing Things",a:"I write and speak to find out what I think, not to announce what I already decided.",p:"Write about the thing you're confused by, before you resolve it.",k:["writing","thinking","discovery","confusion"],src:"After Baldwin on writing as investigation"},

/* ---------- Toni Morrison ---------- */
{id:"morrison-01",au:"morrison",s:"Making Things",a:"If the thing I want doesn't exist yet, that is a brief, not a disappointment.",p:"Start the thing you've been waiting for someone else to make.",k:["creation","initiative","absence","making"],src:"After Morrison on writing the book you want to read"},
{id:"morrison-02",au:"morrison",s:"Making Things",a:"The point of getting free is to free somebody else; the point of power is to give it away.",p:"Use one advantage you hold today on behalf of someone who lacks it.",k:["freedom","power","service","liberation"],src:"After Morrison on the function of freedom"},
{id:"morrison-03",au:"morrison",s:"Making Things",a:"I am my own best thing, and I stop outsourcing that verdict.",p:"Write down one quality of yours you value that nobody has ever praised you for.",k:["self-worth","validation","independence","identity"],src:"After Beloved"},
{id:"morrison-04",au:"morrison",s:"Making Things",a:"I refuse to make my work small so that it fits comfortably in somebody else's imagination.",p:"Restore one thing you edited out of your work to make it more palatable.",k:["audience","compromise","authenticity","scale"],src:"After Morrison on writing without an external gaze"},
{id:"morrison-05",au:"morrison",s:"Making Things",a:"Language is not decoration; it is the measure of how carefully we are living.",p:"Say one thing today with real precision instead of the easy approximate phrase.",k:["language","precision","care","expression"],src:"After Morrison's Nobel lecture on language"},
{id:"morrison-06",au:"morrison",s:"Making Things",a:"When someone shows me the whole of their attention, they have given me something; I try to hand it back.",p:"Give one person your undivided attention for the length of a conversation.",k:["attention","presence","generosity","listening"],src:"After Morrison on truly seeing people"},
{id:"morrison-07",au:"morrison",s:"Making Things",a:"Suffering is not automatically instructive; I have to do the work of turning it into something.",p:"Take one hard experience and write what, specifically, it taught you.",k:["suffering","meaning","work","transformation"],src:"After Morrison on the labour of making meaning"},
{id:"morrison-08",au:"morrison",s:"Making Things",a:"Distraction is a tactic; my job is to keep working while it's deployed.",p:"Identify what's currently pulling your attention off your real work, and put it down.",k:["distraction","focus","work","discipline"],src:"After Morrison on the function of distraction"},
{id:"morrison-09",au:"morrison",s:"Making Things",a:"I write about my own world at full detail rather than translating it for outsiders.",p:"Explain something from your life without simplifying it for an imagined stranger.",k:["specificity","translation","voice","detail"],src:"After Morrison on refusing to explain her world"},
{id:"morrison-10",au:"morrison",s:"Making Things",a:"Editing is not the enemy of the work; it is most of the work.",p:"Cut a fifth out of the last thing you wrote and see what improves.",k:["editing","craft","revision","rigour"],src:"After Morrison's decades as an editor at Random House"},

/* ---------- Maya Angelou ---------- */
{id:"angelou-01",au:"angelou",s:"Resilience & Grace",a:"People will forget what I said and did, but not how I left them feeling.",p:"Leave one interaction today better than you found it, deliberately.",k:["impact","feeling","kindness","memory"],src:"After the observation widely attributed to Angelou"},
{id:"angelou-02",au:"angelou",s:"Resilience & Grace",a:"I may meet defeats, but I refuse to be defeated \u2014 those are different words for a reason.",p:"Separate the setback from the story you've started telling about yourself.",k:["defeat","resilience","distinction","persistence"],src:"After Angelou on encountering defeats"},
{id:"angelou-03",au:"angelou",s:"Resilience & Grace",a:"Courage is the virtue that makes the others possible; without it, kindness collapses under pressure.",p:"Do the small brave thing you've deferred twice already.",k:["courage","virtue","pressure","consistency"],src:"After Angelou on courage as the greatest virtue"},
{id:"angelou-04",au:"angelou",s:"Resilience & Grace",a:"When someone shows me who they are, I believe them the first time.",p:"Stop explaining away one pattern of behaviour you've been excusing.",k:["patterns","trust","clarity","boundaries"],src:"After Angelou on believing people the first time"},
{id:"angelou-05",au:"angelou",s:"Resilience & Grace",a:"I did the best I could with what I knew, and when I knew better I did better \u2014 without back-dating the guilt.",p:"Forgive one past decision you made with less information than you have now.",k:["forgiveness","growth","hindsight","guilt"],src:"After Angelou on knowing better and doing better"},
{id:"angelou-06",au:"angelou",s:"Resilience & Grace",a:"I try to be a rainbow in somebody else's cloud, especially on days my own weather is poor.",p:"Encourage one person today when you least feel like it.",k:["encouragement","generosity","weather","others"],src:"After Angelou on being a rainbow in someone's cloud"},
{id:"angelou-07",au:"angelou",s:"Resilience & Grace",a:"Nothing will work unless I do; inspiration is not a delivery service.",p:"Do twenty minutes on the thing you've been waiting to feel ready for.",k:["work","inspiration","effort","readiness"],src:"After Angelou on nothing working unless you do"},
{id:"angelou-08",au:"angelou",s:"Resilience & Grace",a:"There is no greater agony than an untold story carried inside; I would rather tell it badly than carry it.",p:"Tell one person the thing you've never said out loud.",k:["story","silence","expression","release"],src:"After I Know Why the Caged Bird Sings"},
{id:"angelou-09",au:"angelou",s:"Resilience & Grace",a:"Style is what I do with the hand I was actually dealt.",p:"Do one ordinary task today with more care and craft than it strictly requires.",k:["style","craft","circumstance","dignity"],src:"After Angelou on style and survival"},
{id:"angelou-10",au:"angelou",s:"Resilience & Grace",a:"I am human, so nothing human is foreign to me \u2014 including the parts I'd rather disown.",p:"Notice one trait you condemn in others and find its smaller version in yourself.",k:["humanity","judgement","self-honesty","empathy"],src:"After Angelou's use of the Terence maxim"},

/* ---------- Peter Drucker ---------- */
{id:"drucker-01",au:"drucker",s:"Effectiveness",a:"Doing the right things beats doing things right; efficiency at the wrong task is expensive.",p:"Before optimising anything today, ask whether it should be done at all.",k:["effectiveness","efficiency","priorities","judgement"],src:"After Drucker on effectiveness versus efficiency"},
{id:"drucker-02",au:"drucker",s:"Effectiveness",a:"I record where my time actually goes before I attempt to manage it; memory is an unreliable witness.",p:"Log your time honestly for three days before changing a single thing.",k:["time","measurement","honesty","baseline"],src:"After The Effective Executive on recording time"},
{id:"drucker-03",au:"drucker",s:"Effectiveness",a:"I build on strengths \u2014 mine and other people's \u2014 because remediating weakness rarely produces excellence.",p:"Assign or claim one task on the basis of who is genuinely best at it.",k:["strengths","weakness","assignment","excellence"],src:"After Drucker on building on strength"},
{id:"drucker-04",au:"drucker",s:"Effectiveness",a:"I write down what I expect to happen, then compare it with what did; that comparison is where learning lives.",p:"Record your expected outcome for one decision, with a date to check it.",k:["feedback analysis","expectations","learning","review"],src:"After Drucker's feedback analysis method in Managing Oneself"},
{id:"drucker-05",au:"drucker",s:"Effectiveness",a:"Asking what I should stop doing is more productive than asking what I should add.",p:"Abandon one activity this week that no longer earns its place.",k:["abandonment","stopping","focus","pruning"],src:"After Drucker on systematic abandonment"},
{id:"drucker-06",au:"drucker",s:"Effectiveness",a:"My question is not what I want to accomplish but what I can contribute here that nobody else will.",p:"Identify your unique contribution to your current project and spend today on that.",k:["contribution","uniqueness","focus","value"],src:"After The Effective Executive on contribution"},
{id:"drucker-07",au:"drucker",s:"Effectiveness",a:"The purpose of the work is out there with the person it serves, not in here with my process.",p:"Talk to one actual user, customer or beneficiary this week.",k:["customer","purpose","outside","service"],src:"After Drucker on the purpose of a business"},
{id:"drucker-08",au:"drucker",s:"Effectiveness",a:"I concentrate on one thing at a time, because doing several things adequately is how nothing gets done well.",p:"Pick the single most important task and finish it before opening anything else.",k:["concentration","single-tasking","focus","completion"],src:"After The Effective Executive on concentration"},
{id:"drucker-09",au:"drucker",s:"Effectiveness",a:"I know how I learn \u2014 by reading or by listening \u2014 and I stop fighting my own wiring.",p:"Notice whether you absorb things better read or heard, and arrange your inputs accordingly.",k:["learning style","self-knowledge","method","wiring"],src:"After Managing Oneself"},
{id:"drucker-10",au:"drucker",s:"Effectiveness",a:"Every decision needs a name, a deadline and a person; without those it is only a conversation.",p:"Convert one open discussion into a decision with an owner and a date.",k:["decisions","ownership","deadlines","accountability"],src:"After Drucker on effective decision-making"},

/* ---------- Stephen R. Covey ---------- */
{id:"covey-01",au:"covey",s:"Habits & Character",a:"I act on my conditions rather than react to them; between stimulus and response I have room to choose.",p:"Catch one reactive moment today and choose a different response.",k:["proactive","response","choice","initiative"],src:"After Habit 1: Be Proactive"},
{id:"covey-02",au:"covey",s:"Habits & Character",a:"I start with the end in mind, because a ladder against the wrong wall gets you nowhere efficiently.",p:"Write what you want this project to have produced when it's finished.",k:["vision","end in mind","direction","planning"],src:"After Habit 2: Begin with the End in Mind"},
{id:"covey-03",au:"covey",s:"Habits & Character",a:"I put first things first, which mostly means protecting what is important before it becomes urgent.",p:"Schedule one important-but-not-urgent task before the urgent ones arrive.",k:["priorities","urgent","important","quadrant two"],src:"After Habit 3: Put First Things First"},
{id:"covey-04",au:"covey",s:"Habits & Character",a:"I look for the arrangement where both sides genuinely win, and I'm willing to walk if there isn't one.",p:"Reframe one negotiation this week around what would make both parties glad.",k:["win-win","negotiation","mutual","integrity"],src:"After Habit 4: Think Win-Win"},
{id:"covey-05",au:"covey",s:"Habits & Character",a:"I seek to understand before I ask to be understood; diagnosis precedes prescription everywhere else, too.",p:"In your next disagreement, restate their position until they agree you've got it.",k:["listening","understanding","empathy","diagnosis"],src:"After Habit 5: Seek First to Understand"},
{id:"covey-06",au:"covey",s:"Habits & Character",a:"Difference is where the value is; if we both think the same, one of us is redundant.",p:"Deliberately involve someone who sees the problem differently from you.",k:["synergy","difference","collaboration","value"],src:"After Habit 6: Synergize"},
{id:"covey-07",au:"covey",s:"Habits & Character",a:"I sharpen the saw, because working with a blunt one and calling it dedication is just slow.",p:"Take the break, the walk, or the hour of learning you've been skipping.",k:["renewal","rest","maintenance","sharpen the saw"],src:"After Habit 7: Sharpen the Saw"},
{id:"covey-08",au:"covey",s:"Habits & Character",a:"I spend my energy inside my circle of influence, and it quietly grows.",p:"List one worry you can't affect and one you can, then work only on the second.",k:["circle of influence","concern","control","energy"],src:"After Covey on circles of influence and concern"},
{id:"covey-09",au:"covey",s:"Habits & Character",a:"Every small kept promise is a deposit; trust is a balance, not a declaration.",p:"Make one small deposit today \u2014 a kept word, a remembered detail, an apology.",k:["trust","emotional bank account","promises","relationships"],src:"After Covey on the emotional bank account"},
{id:"covey-10",au:"covey",s:"Habits & Character",a:"Character comes before technique; personality tricks fail exactly when the pressure is on.",p:"Fix one habit rather than one presentation.",k:["character ethic","personality","integrity","substance"],src:"After Covey on the character ethic"},

/* ---------- Dale Carnegie ---------- */
{id:"carnegie-01",au:"carnegie",s:"People Skills",a:"I make more friends by being interested than by being interesting.",p:"Ask three real questions before you say anything about yourself today.",k:["interest","curiosity","friendship","listening"],src:"After How to Win Friends and Influence People"},
{id:"carnegie-02",au:"carnegie",s:"People Skills",a:"Criticism almost never produces change; it produces defence.",p:"Replace one piece of criticism today with a specific request.",k:["criticism","defensiveness","change","requests"],src:"After Carnegie on not criticising, condemning or complaining"},
{id:"carnegie-03",au:"carnegie",s:"People Skills",a:"A person's own name is the sweetest sound to them, and remembering it costs me almost nothing.",p:"Learn and use the name of one person you usually pass anonymously.",k:["names","recognition","respect","attention"],src:"After Carnegie on remembering names"},
{id:"carnegie-04",au:"carnegie",s:"People Skills",a:"Nobody ever won an argument; they only won the exchange and lost the person.",p:"Let one small point go today and keep the relationship instead.",k:["arguments","winning","relationships","restraint"],src:"After Carnegie on the futility of arguments"},
{id:"carnegie-05",au:"carnegie",s:"People Skills",a:"When I'm wrong I say so quickly and emphatically, which removes the other person's whole speech.",p:"Admit one error today before anyone has to point it out.",k:["admitting","error","speed","disarming"],src:"After Carnegie on admitting mistakes quickly"},
{id:"carnegie-06",au:"carnegie",s:"People Skills",a:"Appreciation is specific and sincere; flattery is generic and cheap, and everyone can tell.",p:"Praise one exact thing someone did, rather than praising them in general.",k:["appreciation","flattery","specificity","sincerity"],src:"After Carnegie on honest appreciation"},
{id:"carnegie-07",au:"carnegie",s:"People Skills",a:"I let the other person save face; humiliation buys compliance and loses everything else.",p:"Correct someone privately today rather than in front of others.",k:["face","dignity","correction","privacy"],src:"After Carnegie on letting people save face"},
{id:"carnegie-08",au:"carnegie",s:"People Skills",a:"I talk in terms of what they want, because that is the only channel anybody is really listening on.",p:"Rewrite one request from their point of view before you send it.",k:["persuasion","interests","framing","empathy"],src:"After Carnegie on talking in terms of the other person's interests"},
{id:"carnegie-09",au:"carnegie",s:"People Skills",a:"I live in day-tight compartments, because most of what I worry about is not scheduled for today.",p:"Write down tomorrow's worry, close the notebook, and deal with today.",k:["worry","present","compartments","anxiety"],src:"After How to Stop Worrying and Start Living"},
{id:"carnegie-10",au:"carnegie",s:"People Skills",a:"I accept the worst that could happen, then calmly set about improving on it.",p:"Name the actual worst case of your current worry, then list what you'd do next.",k:["worst case","acceptance","calm","planning"],src:"After Carnegie's formula for dealing with worry"},

/* ---------- Napoleon Hill ---------- */
{id:"hill-01",au:"hill",s:"Purpose & Persistence",a:"A vague ambition is a wish; a definite aim with a date attached is a plan.",p:"Write your main aim in one sentence with a deadline, and read it twice today.",k:["definite purpose","clarity","deadline","aim"],src:"After Think and Grow Rich on definiteness of purpose"},
{id:"hill-02",au:"hill",s:"Purpose & Persistence",a:"Two minds working on the same problem produce a third thing neither had alone.",p:"Bring one stuck problem to a person you trust this week.",k:["mastermind","collaboration","thinking","help"],src:"After Hill on the mastermind principle"},
{id:"hill-03",au:"hill",s:"Purpose & Persistence",a:"Most people quit within sight of the thing; persistence is mostly a refusal to stop three feet early.",p:"Return to one abandoned project and give it one more honest attempt.",k:["persistence","quitting","three feet","endurance"],src:"After the \u201cthree feet from gold\u201d parable in Think and Grow Rich"},
{id:"hill-04",au:"hill",s:"Purpose & Persistence",a:"Every setback carries the seed of an equivalent advantage, but I have to go looking for it.",p:"Find the one usable thing inside your most recent failure.",k:["adversity","advantage","seed","reframing"],src:"After Hill on adversity carrying an equivalent benefit"},
{id:"hill-05",au:"hill",s:"Purpose & Persistence",a:"Desire without a plan is just appetite; I write the plan down and revise it when it fails.",p:"Draft the first version of a plan you've been holding only in your head.",k:["planning","desire","revision","organised effort"],src:"After Think and Grow Rich on organised planning"},
{id:"hill-06",au:"hill",s:"Purpose & Persistence",a:"I do more than I am paid for, on the understanding that this is how the rate gets renegotiated.",p:"Deliver one thing this week that exceeds what was actually asked.",k:["extra mile","value","reputation","initiative"],src:"After Hill on going the extra mile"},
{id:"hill-07",au:"hill",s:"Purpose & Persistence",a:"What I repeatedly tell myself becomes what I expect, and what I expect shapes what I attempt.",p:"Catch one habitual self-statement and replace it with an accurate one.",k:["autosuggestion","self-talk","expectation","belief"],src:"After Think and Grow Rich on autosuggestion"},
{id:"hill-08",au:"hill",s:"Purpose & Persistence",a:"Indecision is a decision, and usually the worst one available.",p:"Make one pending decision today, even imperfectly, and move.",k:["decision","indecision","procrastination","action"],src:"After Hill on the habit of prompt decision"},
{id:"hill-09",au:"hill",s:"Purpose & Persistence",a:"Fear of criticism has cost more people more opportunities than any actual critic ever has.",p:"Do the thing you've avoided because of what people might say.",k:["fear","criticism","opportunity","courage"],src:"After Hill on the six basic fears"},
{id:"hill-10",au:"hill",s:"Purpose & Persistence",a:"Controlled attention is the whole game: I decide what gets my mind, or something else will.",p:"Remove one input that has been taking your attention without earning it.",k:["attention","control","focus","inputs"],src:"After Hill on controlled attention"},

/* ---------- Tony Robbins ---------- */
{id:"robbins-01",au:"robbins",s:"State & Action",a:"Where my focus goes, my energy follows \u2014 so what I choose to look at is not a small decision.",p:"Redirect your attention once today from what's wrong to what's actionable.",k:["focus","energy","attention","direction"],src:"After Robbins on focus and energy"},
{id:"robbins-02",au:"robbins",s:"State & Action",a:"My state changes what I'm capable of, and I can change my state on purpose in about two minutes.",p:"Move your body deliberately before the task you're dreading.",k:["state","physiology","energy","preparation"],src:"After Robbins on state management"},
{id:"robbins-03",au:"robbins",s:"State & Action",a:"The story I tell about a situation is a choice, and a bad story will stop me faster than the facts will.",p:"Write the story you're telling about a current setback, then write a truer one.",k:["story","narrative","belief","reframing"],src:"After Robbins on state, story and strategy"},
{id:"robbins-04",au:"robbins",s:"State & Action",a:"I take massive action rather than measured action, because I can steer once I'm moving.",p:"Do four things towards the goal today instead of researching a fifth option.",k:["action","momentum","volume","execution"],src:"After Robbins on massive action"},
{id:"robbins-05",au:"robbins",s:"State & Action",a:"If someone has already got the result I want, I study their method before inventing my own.",p:"Find one person who has done your goal and reverse-engineer how.",k:["modelling","study","method","shortcut"],src:"After Robbins on modelling excellence"},
{id:"robbins-06",au:"robbins",s:"State & Action",a:"A better question produces a better answer; \u201cwhy me\u201d and \u201cwhat now\u201d lead to different lives.",p:"Replace one complaint with a question that has an answer.",k:["questions","framing","problem-solving","language"],src:"After Robbins on the quality of your questions"},
{id:"robbins-07",au:"robbins",s:"State & Action",a:"It is in my moments of decision that my direction is set, not in my moments of intention.",p:"Turn one intention into a decision with a first action today.",k:["decision","destiny","intention","commitment"],src:"After Robbins on decisions shaping destiny"},
{id:"robbins-08",au:"robbins",s:"State & Action",a:"Progress equals happiness more reliably than arrival does; I set things up so I can feel the movement.",p:"Track one visible measure of progress on your main project this week.",k:["progress","happiness","measurement","momentum"],src:"After Robbins on progress equalling happiness"},
{id:"robbins-09",au:"robbins",s:"State & Action",a:"Once my own needs are met, contribution is the only thing that keeps the meaning topped up.",p:"Contribute something with no transactional return this week.",k:["contribution","meaning","six human needs","giving"],src:"After the six human needs, contribution and growth"},
{id:"robbins-10",au:"robbins",s:"State & Action",a:"Complexity is where good intentions go to die; I want the simplest version that works.",p:"Cut your current plan down to the three steps that actually matter.",k:["simplicity","complexity","plans","execution"],src:"After Robbins on simplicity in execution"},

/* ---------- Neil deGrasse Tyson ---------- */
{id:"tyson-01",au:"tyson",s:"Evidence & Perspective",a:"What is true stays true without my agreement, so I hold my beliefs loosely enough that evidence can move them.",p:"Name one belief you hold and state what evidence would change it. If nothing would, it isn't a belief \u2014 it's an attachment.",k:["evidence","belief","truth","falsifiability"],src:"After Tyson on science being true whether or not you believe in it"},
{id:"tyson-02",au:"tyson",s:"Evidence & Perspective",a:"\u201cI don't know\u201d is a complete and respectable sentence, and pretending otherwise is how errors get expensive.",p:"Say it once today where you'd normally improvise an answer, then go and find out.",k:["ignorance","humility","honesty","admitting"],src:"After Tyson on the value of admitting ignorance"},
{id:"tyson-03",au:"tyson",s:"Evidence & Perspective",a:"The universe is under no obligation to make sense to me; my confusion is information about me, not about it.",p:"Take one thing that seems obviously wrong and check whether you've understood it before you dismiss it.",k:["confusion","reality","intuition","humility"],src:"After Tyson on the universe's lack of obligation"},
{id:"tyson-04",au:"tyson",s:"Evidence & Perspective",a:"I keep three piles separate: what I know, what I don't know, and what I cannot know \u2014 and I notice when I'm mixing them.",p:"Sort your current problem into those three piles and act only on the first.",k:["knowledge","uncertainty","limits","clarity"],src:"After Tyson on the boundaries of knowledge"},
{id:"tyson-05",au:"tyson",s:"Evidence & Perspective",a:"An objective truth, a personal truth and a political truth are three different animals, and most arguments are people mistaking one for another.",p:"In your next disagreement, work out which of the three you're each actually defending.",k:["objective truth","personal truth","argument","categories"],src:"After Starry Messenger"},
{id:"tyson-06",au:"tyson",s:"Evidence & Perspective",a:"Seen from far enough away, most of what I'm defending is a line somebody drew, and I can choose how hard to defend it.",p:"Take one conflict you're in and describe it as it would look from orbit.",k:["cosmic perspective","conflict","scale","tribalism"],src:"After the cosmic perspective in Starry Messenger"},
{id:"tyson-07",au:"tyson",s:"Evidence & Perspective",a:"I'm bad at probability by default, so I do the arithmetic instead of trusting the feeling.",p:"Before your next risk judgement, write down the actual numbers rather than how alarming it seems.",k:["probability","innumeracy","risk","arithmetic"],src:"After Tyson on innumeracy and misjudged risk"},
{id:"tyson-08",au:"tyson",s:"Evidence & Perspective",a:"Children are born curious and get trained out of it; I try to be untrained.",p:"Ask one question today that you'd normally think was too basic to ask out loud.",k:["curiosity","questions","children","learning"],src:"After Tyson on children as natural scientists"},
{id:"tyson-09",au:"tyson",s:"Evidence & Perspective",a:"Being taught what to think produces someone who can be told anything; I'd rather learn how to think.",p:"Take one claim you accepted this week and trace it back to where it actually came from.",k:["critical thinking","education","method","sources"],src:"After Tyson on scientific literacy as a way of thinking"},
{id:"tyson-10",au:"tyson",s:"Evidence & Perspective",a:"I'm not small in the universe \u2014 I'm made of it, and that is a better fact than the one that makes people feel tiny.",p:"When the scale of things feels crushing today, try the other reading of the same fact.",k:["belonging","cosmos","scale","perspective"],src:"After Tyson on being part of the universe rather than dwarfed by it"}

];
